def isStronglyConnected(n, edges):
    fwd = [[] for _ in range(n)]
    back = [[] for _ in range(n)]
    for u, v in edges:
        fwd[u].append(v)
        back[v].append(u)

    def reaches_all(adj):
        seen = [False] * n
        seen[0] = True
        stack = [0]
        count = 1
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    count += 1
                    stack.append(v)
        return count == n

    return reaches_all(fwd) and reaches_all(back)
